export function callPolyself(services,layout,name,...args){const saved=services.stackSave();try{const env=createPolyselfEnvironment(services,layout);if(['dropp'].includes(name))args[0]=env.view('obj',args[0]);if(name==='mbodypart')args[0]=env.view('monst',args[0]);const result=withCEnvironment(env,()=>core[name](...args));return typeof result==='string'?services.literal(result):result?.address??result;}finally{services.stackRestore(saved);}}
